import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    m = draw(st.integers(1, 8))
    queries = []
    for _ in range(m):
        idx = draw(st.integers(0, n - 1))
        color = draw(st.integers(1, 3))
        queries.append([idx, color])
    return f"{n}\n{json.dumps(queries)}\n"

def _parse(inp):
    lines = inp.split("\n", 1)
    n = int(lines[0].strip())
    queries = json.loads(lines[1].strip())
    return n, queries

def validate(inp: str) -> bool:
    try:
        parts = inp.split("\n", 1)
        if len(parts) != 2:
            return False
        if parts[0].strip() != str(int(parts[0].strip())):
            return False
        n, queries = _parse(inp)
    except Exception:
        return False
    if not (isinstance(n, int) and 1 <= n <= 10**5):
        return False
    if not isinstance(queries, list) or not (1 <= len(queries) <= 10**5):
        return False
    for q in queries:
        if not isinstance(q, list) or len(q) != 2:
            return False
        idx, col = q
        if not (isinstance(idx, int) and isinstance(col, int)):
            return False
        if not (0 <= idx <= n - 1):
            return False
        if not (1 <= col <= 10**5):
            return False
    return True

def ref(inp: str) -> str:
    n, queries = _parse(inp)
    nums = [0] * n
    answer = []
    for idx, color in queries:
        nums[idx] = color
        cnt = 0
        for j in range(n - 1):
            if nums[j] == nums[j + 1] and nums[j] != 0:
                cnt += 1
        answer.append(cnt)
    return json.dumps(answer)
